#include <iostream>
#include <vector>
#include <string>

int main() {
    int count;
    std::cin >> count;
    std::cin.ignore(); // skip newline after integer input
    std::string inputLine;
    std::getline(std::cin, inputLine);

    int maxLen = 0;
    std::vector<std::string> parts;
    std::string current;
    bool inParentheses = false;

    for (char ch : inputLine) {
        if (ch == '(') {
            inParentheses = true;
            if (current.length() > maxLen) maxLen = current.length();
            current.clear();
        } else if (ch == ')') {
            inParentheses = false;
            if (!current.empty()) {
                parts.push_back(current);
                current.clear();
            }
        } else if (std::isalpha(static_cast<unsigned char>(ch))) {
            current += ch;
        } else if (ch == '_') {
            if (inParentheses) {
                if (!current.empty()) {
                    parts.push_back(current);
                    current.clear();
                }
            } else {
                if (current.length() > maxLen) maxLen = current.length();
                current.clear();
            }
        }
    }
    if (current.length() > maxLen) maxLen = current.length();

    std::cout << maxLen << " " << parts.size() << std::endl;

    return 0;
}
